style.css:
@-moz-document domain("roblox.com") {
.avatar-image {
        position: relative;
        display: inline-block;
    }
    
    .avatar-image::before {
        content: '';
        position: absolute;
        top: -5px;
        left: -5px;
        right: -5px;
        bottom: -5px;
        border: 5px solid transparent;
        border-radius: 50%;
        background-image: linear-gradient(45deg, red, orange, yellow, green, blue, indigo, violet);
        z-index: -1;
    }
}
